class stringx
{
public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  const char *c_str() const;
};

stringx operator+(const stringx &, const char *);
stringx operator+(const char *, const stringx &);
stringx operator+(const stringx &, const stringx &);

class script_instance
{
public:
  const stringx &get_name() const;
};

class script_executable
{
public:
  const stringx &get_fullname() const;
};

class vm_thread
{
public:
  script_instance *get_instance() const;
  script_executable *get_executable() const;
};

typedef float rational_t;
typedef float vm_num_t;
typedef stringx *vm_str_t;

class vm_stack
{
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;
public:
  vm_thread *get_thread() const { return my_thread; }
  bool push(const char *, int);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual ~function();
    virtual bool operator()(vm_stack &, entry_t) { return true; }
  };
};

class typeface_def
{
public:
  float text_width(const char *) const;
};

extern typeface_def *font;
void error(const stringx &);

class slf_text_width_t : public script_library_class::function
{
  public:
    struct parms_t
    {
      vm_str_t msg;
    };
    virtual bool operator ()(vm_stack &stack, entry_t entry)
    {
      parms_t* parms = (parms_t*)stack.get_thread();
      vm_num_t result = (rational_t)font->text_width((*parms->msg).c_str());
      if (!stack.push((char*)&result,sizeof(result)) )
        error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
      return true;
    }
};
